SELECT CASE WHEN budget >= 3334000 THEN 'high' WHEN budget >= 1976000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(budget) AS total_budget, COUNT(*) AS cnt, RANK() OVER (ORDER BY SUM(budget) DESC) AS budget_rank FROM departments WHERE dept_name NOT IN ('Finance', 'Engineering', 'Sales') GROUP BY CASE WHEN budget >= 3334000 THEN 'high' WHEN budget >= 1976000 THEN 'mid' ELSE 'low' END;
